mapper.update:
update game_session
   set leaderboard_visible=#{visible}, leaderboard_updated_by=#{actorMemberId},
       leaderboard_updated_at=#{now}, revision=revision+1, update_time=#{now}
 where id=#{id} and revision=#{expectedRevision} and status=#{status}
   and status in ('PREPARING','READY','RUNNING')

mapper.select:
select  from game_station_run s
 where s.game_session_id=#{sessionId} and s.merchant_member_id=#{merchantMemberId}
 order by s.id

select count(1) from game_station_run
 where merchant_member_id=#{merchantMemberId}
   and node_id=#{nodeId}
   and status in ('READY', 'ACTIVE')

mapper.update:
update game_station_run
   set status=#{toStatus}, preparation_snapshot_json=#{station.preparationSnapshotJson},
       capacity=#{station.capacity}, service_start_at=#{station.serviceStartAt},
       service_end_at=#{station.serviceEndAt}, pause_reason_code=#{station.pauseReasonCode},
       pause_reason=#{station.pauseReason}, resume_eta=#{station.resumeEta},
       fallback_node_id=#{station.fallbackNodeId}, fallback_plan_code=#{station.fallbackPlanCode},
       fallback_plan_version=#{station.fallbackPlanVersion}, revision=revision+1, update_time=#{now}
 where id=#{station.id} and game_session_id=#{station.gameSessionId}
   and merchant_member_id <=> #{merchantMemberId} and status=#{fromStatus}
   and revision=#{expectedRevision}

mapper.select:
select count(1) from game_team_role_assignment
 where game_session_id=#{sessionId} and role_code=#{roleCode}
   and status in ('ASSIGNED','CONFIRMED')

mapper.update:
update game_team_role_assignment
   set status='SUPERSEDED', superseded_by=#{supersededBy}, superseded_at=#{now},
       revision=revision+1, update_time=#{now}
 where game_session_id=#{sessionId} and member_id=#{memberId}
   and status in ('ASSIGNED','CONFIRMED')

update game_story_state set variables_json=#{variablesJson}, applied_choices_json=#{appliedChoicesJson},
       ending_code=#{endingCode}, status=#{status}, revision=revision+1, update_time=#{updateTime}
 where id=#{id} and game_session_id=#{gameSessionId} and owner_type=#{ownerType}
   and owner_id=#{ownerId} and revision=#{revision} and status<>'ENDING_RESOLVED'

update game_command_receipt set game_session_id=#{gameSessionId}, outcome=#{outcome},
       reason_code=#{reasonCode}, revision=#{revision}, result_json=#{resultJson}, update_time=#{updateTime}
 where id=#{id} and outcome='PENDING' and request_hash=#{requestHash}

update game_task_submission set status=#{status}, decided_by=#{decidedBy},
       decision_reason_code=#{decisionReasonCode}, decision_reason=#{decisionReason},
       revision=revision+1, update_time=#{updateTime}
 where id=#{id} and game_session_id=#{gameSessionId} and station_run_id=#{stationRunId}
   and status='PENDING' and revision=#{revision}

mapper.select:
select id, game_session_id, activity_id, sender_member_id, target_type, target_id,
       role_code, content, status, create_time, update_time
  from game_broadcast where id=#{id}
